var s=[{title:`A mérés módjai`,text:`Az új terhelési rekordot könnyű észrevenni, de 10 kontrollált ismétlés egy olyan súllyal, amellyel korábban hét ment, szintén fejlődés. Saját testsúlyos gyakorlatoknál javulhatsz a fekvőtámasz dőlésszögének csökkentésével, a mozgástartomány növelésével vagy a segítettről a segítség nélküli ismétlésekre való átlépéssel.`},{title:`Becsült és tesztelt maximumok`,text:`Az egyismétléses maximumod (1RM) a legnehezebb terhelés, amelyet elfogadható technikával egy ismétlésre fel tudsz emelni. A képletek becsülhetik könnyebb sorozatokból, de a becslések kevésbé megbízhatóak különböző gyakorlatok, nagyobb ismétlésszámok és különböző emelők között. A kezdőknek nincs szükségük maximumtesztekre a fejlődés követéséhez.`},{title:`Hasonlítsd a hasonlót`,text:`A fogást, a mélységet, a tempót, a felszerelést és a pihenőt tartsd nagyjából ugyanazon, amikor edzéseket hasonlítasz össze. Egy nehezebb részleges guggolás nem automatikusan egyenlő egy könnyebb teljes tartományú guggolással. A nagyobb kontroll, magabiztosság vagy állóképesség ugyanazzal a terheléssel is javulásnak számít, új maximummal vagy anélkül.`},{title:`Példa`,text:`Egy evezés 3 × 8-ról 3 × 12-re megy ugyanazzal a súlyzóval és hasonló technikával. Ezután próbálhatsz egy kis terhelésnövelést, és visszadolgozhatod magad az ismétlési tartományon.`},{title:`A TrainUp használata`,text:`A TrainUp nem ír elő súlyokat: te választod a terhelést. A terved minden gyakorlathoz sorozatokat és ismétléseket ad, edzés közben pedig rögzíted a ténylegesen elvégzett ismétléseidet.`}];var l=[{label:`2026-os ACSM állásfoglalás`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`ACSM 2026-os gyakorlati útmutató`,url:`https://www.acsm.org/wp-content/uploads/2026/03/Resistance-Training-Position-Stand-infographic.pdf`}];var a={sections:s,sources:l};export{a as default,s as sections,l as sources};